package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FingerprintVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property fingerprint of observed issue ")
  void test_fingerprint_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> FingerprintVO.tryFrom(null));
    Assertions.assertEquals("one", FingerprintVO.from("one").getFingerprint());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> FingerprintVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", FingerprintVO.from("one").toString());
  }
}
